head.script:
scwin.log = function(msg) {
    var cur = txa_log.getValue();
    var ts = new Date().toLocaleTimeString();
    var line = "[" + ts + "] " + msg;
    txa_log.setValue(cur ? cur + "\n" + line : line);
};

scwin.btn_search_onclick = function() {
    var domId = ipt_domId.getValue().trim();
    if (!domId) {
        scwin.log("DOM ID를 입력해주세요.");
        return;
    }
    var comp = $p.debug.getComponentByDom(domId);
    if (comp) {
        scwin.log("── getComponentByDom(\"" + domId + "\") ──");
        scwin.log("  id         : " + comp.getID());
        scwin.log("  originalId : " + comp.getOriginalID());
        scwin.log("  pluginName : " + (comp.options.pluginName || comp.options.pluginName || ""));
        scwin.log("  scope_id   : " + (comp.scope_id || ""));
    } else {
        scwin.log("결과 없음 — \"" + domId + "\" 에 해당하는 컴포넌트를 찾지 못했습니다.");
    }
};

scwin.btn_batch_onclick = function() {
    var domId = ipt_domId.getValue().trim();
    if (!domId) {
        scwin.log("DOM ID를 입력해주세요.");
        return;
    }
    var ids = domId.split(",").map(function(s) { return s.trim(); }).filter(Boolean);
    var mapping = $p.debug.getComponentsByDom(ids);
    scwin.log("── getComponentsByDom(" + JSON.stringify(ids) + ") ──");
    for (var key in mapping) {
        var comp = mapping[key];
        if (comp) {
            scwin.log("  " + key + " → originalId: " + comp.getOriginalID() + ", type: " + (comp.options.pluginName || ""));
        } else {
            scwin.log("  " + key + " → null");
        }
    }
};

scwin.btn_clear_onclick = function() {
    txa_log.setValue("");
};

scwin.onpageload = function() {
    dataMap1.set("domId", "mf_grd_main_cell_0_0");
    dataList1.setJSON([
        { COL1: "item1", COL2: "val1" },
        { COL1: "item2", COL2: "val2" },
        { COL1: "item3", COL2: "val3" }
    ]);
};
